<script>addEventListener('DOMContentLoaded',()=>{const closureIds=@json($case->quotes->where('quote_type','closure')->pluck('id')->values());document.querySelectorAll('.quote-line').forEach(line=>{const link=line.querySelector('a[href*="data-recovery-quotes"]');if(!link)return;const id=Number(link.href.split('/').filter(Boolean).pop());if(!closureIds.includes(id))return;const strong=line.querySelector('strong');if(strong)strong.insertAdjacentHTML('afterend','<br><small>Liquidación de cierre</small>');const button=[...line.querySelectorAll('a.btn')].pop();if(button)button.textContent='Ver liquidación'})})</script>
